import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  getRiskScore, 
  getRecommendation, 
  getConsistencyAnalysis 
} from '../api/api';
import SimpleButton from '../components/SimpleButton';

const SimpleDashboard = () => {
  const navigate = useNavigate();
  const [companyData, setCompanyData] = useState(null);
  const [riskAnalysis, setRiskAnalysis] = useState(null);
  const [recommendation, setRecommendation] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const loadData = async () => {
      try {
        const storedCompanyData = localStorage.getItem('companyData');

        if (!storedCompanyData) {
          navigate('/');
          return;
        }

        const companyData = JSON.parse(storedCompanyData);
        setCompanyData(companyData);

        // Load risk analysis
        const riskResponse = await getRiskScore();
        if (riskResponse.status === 'success') {
          setRiskAnalysis(riskResponse.risk_analysis);
          localStorage.setItem('riskAnalysis', JSON.stringify(riskResponse.risk_analysis));
        }

        // Load recommendation
        const recResponse = await getRecommendation();
        if (recResponse.status === 'success') {
          setRecommendation(recResponse.recommendation);
          localStorage.setItem('recommendation', JSON.stringify(recResponse.recommendation));
        }

      } catch (err) {
        setError('Failed to load dashboard data: ' + err.message);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [navigate]);

  const formatCurrency = (amount) => {
    if (amount >= 10000000) {
      return `₹${(amount / 10000000).toFixed(2)} Cr`;
    } else if (amount >= 100000) {
      return `₹${(amount / 100000).toFixed(2)} L`;
    } else {
      return `₹${amount.toLocaleString()}`;
    }
  };

  const getRecommendationColor = (decision) => {
    switch (decision?.toLowerCase()) {
      case 'approve':
        return 'text-green-600 bg-green-100';
      case 'conditional approval':
        return 'text-yellow-600 bg-yellow-100';
      case 'reject':
        return 'text-red-600 bg-red-100';
      default:
        return 'text-gray-600 bg-gray-100';
    }
  };

  const getRiskCategoryColor = (category) => {
    switch (category?.toLowerCase()) {
      case 'very high':
        return 'text-red-600 bg-red-100';
      case 'high':
        return 'text-orange-600 bg-orange-100';
      case 'medium':
        return 'text-yellow-600 bg-yellow-100';
      case 'low':
        return 'text-blue-600 bg-blue-100';
      case 'very low':
        return 'text-green-600 bg-green-100';
      default:
        return 'text-gray-600 bg-gray-100';
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-lg text-gray-600">Loading your credit analysis...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="text-6xl mb-4">⚠️</div>
          <h2 className="text-2xl font-bold text-red-600 mb-2">Error Loading Dashboard</h2>
          <p className="text-gray-600">{error}</p>
          <SimpleButton onClick={() => window.location.reload()} className="mt-6">
            Try Again
          </SimpleButton>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen py-8">
      <div className="max-w-7xl mx-auto px-4">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 mb-2">
                Credit Analysis Dashboard
              </h1>
              <p className="text-lg text-gray-600">
                {companyData?.company || 'Company'} - Comprehensive Risk Assessment
              </p>
            </div>
            <div className="flex space-x-3">
              <SimpleButton
                onClick={() => navigate('/research')}
                className="bg-blue-600 hover:bg-blue-700"
              >
                Research
              </SimpleButton>
              <SimpleButton
                onClick={() => navigate('/cam-preview')}
                className="bg-green-600 hover:bg-green-700"
              >
                Generate CAM
              </SimpleButton>
            </div>
          </div>
        </div>

        {/* Key Metrics */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          <div className="bg-white rounded-lg shadow-md p-6 text-center">
            <div className="text-6xl mb-4">🛡️</div>
            <h3 className="text-lg font-semibold text-gray-900 mb-1">Risk Score</h3>
            <div className="text-3xl font-bold text-blue-600">
              {riskAnalysis?.risk_score || 0}
              <span className="text-lg text-gray-500">/100</span>
            </div>
            <div className={`mt-2 px-3 py-1 rounded-full text-sm font-medium ${getRiskCategoryColor(riskAnalysis?.risk_category)}`}>
              {riskAnalysis?.risk_category || 'Unknown'}
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6 text-center">
            <div className="text-6xl mb-4">✅</div>
            <h3 className="text-lg font-semibold text-gray-900 mb-1">Decision</h3>
            <div className={`text-2xl font-bold ${getRecommendationColor(recommendation?.decision)}`}>
              {recommendation?.decision || 'Pending'}
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6 text-center">
            <div className="text-6xl mb-4">💰</div>
            <h3 className="text-lg font-semibold text-gray-900 mb-1">Loan Limit</h3>
            <div className="text-2xl font-bold text-purple-600">
              {formatCurrency(recommendation?.loan_limit || 0)}
            </div>
          </div>

          <div className="bg-white rounded-lg shadow-md p-6 text-center">
            <div className="text-6xl mb-4">📈</div>
            <h3 className="text-lg font-semibold text-gray-900 mb-1">Interest Rate</h3>
            <div className="text-2xl font-bold text-orange-600">
              {recommendation?.interest_rate || 0}%
            </div>
          </div>
        </div>

        {/* Financial Overview */}
        {companyData && (
          <div className="bg-white rounded-lg shadow-md p-8 mb-8">
            <h3 className="text-xl font-bold text-gray-900 mb-6">Financial Overview</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div className="bg-blue-50 p-4 rounded-lg">
                <p className="text-sm text-blue-600 font-medium">Revenue</p>
                <p className="text-xl font-bold text-blue-900">
                  {formatCurrency(companyData.revenue || 0)}
                </p>
              </div>
              <div className="bg-green-50 p-4 rounded-lg">
                <p className="text-sm text-green-600 font-medium">Assets</p>
                <p className="text-xl font-bold text-green-900">
                  {formatCurrency(companyData.assets || 0)}
                </p>
              </div>
              <div className="bg-red-50 p-4 rounded-lg">
                <p className="text-sm text-red-600 font-medium">Liabilities</p>
                <p className="text-xl font-bold text-red-900">
                  {formatCurrency(companyData.liabilities || 0)}
                </p>
              </div>
              <div className="bg-purple-50 p-4 rounded-lg">
                <p className="text-sm text-purple-600 font-medium">Profit</p>
                <p className="text-xl font-bold text-purple-900">
                  {formatCurrency(companyData.profit || 0)}
                </p>
              </div>
            </div>
          </div>
        )}

        {/* Risk Factors */}
        {riskAnalysis?.risk_factors && (
          <div className="bg-white rounded-lg shadow-md p-8 mb-8">
            <h3 className="text-xl font-bold text-gray-900 mb-6">Key Risk Factors</h3>
            <div className="space-y-3">
              {riskAnalysis.risk_factors.slice(0, 5).map((factor, index) => (
                <div
                  key={index}
                  className="flex items-start space-x-3 p-3 bg-red-50 rounded-lg border-l-4 border-red-400"
                >
                  <div className="text-2xl">⚠️</div>
                  <p className="text-sm text-gray-700">{factor}</p>
                </div>
              ))}
              {riskAnalysis.risk_factors.length === 0 && (
                <div className="text-center py-8">
                  <div className="text-4xl mb-4">✅</div>
                  <p className="text-gray-600">No significant risk factors identified</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Recommendation Details */}
        {recommendation && (
          <div className="bg-white rounded-lg shadow-md p-8 mb-8">
            <h3 className="text-xl font-bold text-gray-900 mb-6">Loan Recommendation Details</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <h4 className="font-semibold text-gray-900 mb-4">Loan Terms</h4>
                <div className="space-y-3">
                  <div className="flex justify-between">
                    <span className="text-gray-600">Principal Amount</span>
                    <span className="font-medium text-gray-900">
                      {formatCurrency(recommendation.loan_limit)}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">Interest Rate</span>
                    <span className="font-medium text-gray-900">
                      {recommendation.interest_rate}% p.a.
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">Tenure</span>
                    <span className="font-medium text-gray-900">
                      {recommendation.tenure_months} months
                    </span>
                  </div>
                </div>
              </div>
              <div>
                <h4 className="font-semibold text-gray-900 mb-4">Conditions</h4>
                <div className="space-y-2">
                  {recommendation.conditions?.map((condition, index) => (
                    <div
                      key={index}
                      className="flex items-start space-x-2 p-3 bg-yellow-50 rounded-lg"
                    >
                      <div className="w-2 h-2 bg-yellow-400 rounded-full mt-1.5"></div>
                      <p className="text-sm text-gray-700">{condition}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="mt-6 flex justify-center">
              <SimpleButton
                onClick={() => navigate('/cam-preview')}
                className="bg-green-600 hover:bg-green-700"
                size="lg"
              >
                Generate Full Report
              </SimpleButton>
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="mt-8 flex justify-center space-x-4">
          <SimpleButton
            onClick={() => navigate('/')}
            className="bg-gray-600 hover:bg-gray-700"
          >
            Upload New Documents
          </SimpleButton>
          <SimpleButton
            onClick={() => window.location.reload()}
            className="bg-yellow-500 hover:bg-yellow-600"
          >
            Refresh Analysis
          </SimpleButton>
        </div>
      </div>
    </div>
  );
};

export default SimpleDashboard;
